(function () {
  const lead = Object.assign({}, $json);
  const email = String(lead.email || '').toLowerCase();
  const title = String(lead.title || '').toLowerCase();
  const freeMail = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
  let score = 0;
  if (email.indexOf('@') > 0 && freeMail.indexOf(email.split('@')[1]) < 0) score += 30;
  if (lead.company) score += 20;
  if (/(founder|ceo|cto|vp|head|director)/.test(title)) score += 30;
  if (Number(lead.employees || 0) >= 50) score += 20;
  lead.score = score;
  lead.tier = score >= 60 ? 'hot' : (score >= 30 ? 'warm' : 'cold');
  lead.hot = score >= 60;
  return [lead];
})()
